import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const patterns = [
  "/images/ai/",
  "/ai-generated/",
  "ai-generated",
  "generated-by-ai",
  "generated_with_ai",
  "gpt",
  "chatgpt",
  "ai-representative",
  "AI-generated",
  "Generated by AI",
];
const map = JSON.parse(fs.readFileSync(path.join(root, "docs/stage-1b-media-migration-map.json"), "utf8"));
const oldPaths = map.entries.map((entry) => entry.oldPath);
const scanRoots = [path.join(root, ".next/server"), path.join(root, ".next/static"), path.join(root, "public")];
const excluded = new Set([".DS_Store"]);

function walk(dir) {
  if (!fs.existsSync(dir)) return [];
  const files = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (excluded.has(entry.name)) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) files.push(...walk(full));
    else files.push(full);
  }
  return files;
}

const files = scanRoots.flatMap(walk);
const textExtensions = new Set([".js", ".mjs", ".cjs", ".json", ".html", ".xml", ".txt", ".css", ".map", ".webmanifest"]);
const markerMatches = [];
const oldPathMatches = [];
for (const file of files) {
  if (file.startsWith(path.join(root, "public", "media"))) continue;
  if (!textExtensions.has(path.extname(file).toLowerCase())) continue;
  if (file.endsWith(path.join("app", "icon.png", "route.js"))) continue;
  let text;
  try { text = fs.readFileSync(file, "utf8"); } catch { continue; }
  const relative = path.relative(root, file);
  const currentMarkers = patterns.filter((pattern) => text.includes(pattern));
  const currentOldPaths = oldPaths.filter((oldPath) => text.includes(oldPath) && !text.includes(`/media${oldPath}`));
  if (currentMarkers.length) markerMatches.push({ file: relative, patterns: currentMarkers });
  if (currentOldPaths.length) oldPathMatches.push({ file: relative, paths: currentOldPaths });
}

const publicMarkerMatches = markerMatches.filter((entry) => entry.file.startsWith("public/"));
const nextMarkerMatches = markerMatches.filter((entry) => entry.file.startsWith(".next/"));
const publicOldPathMatches = oldPathMatches.filter((entry) => entry.file.startsWith("public/"));
const nextOldPathMatches = oldPathMatches.filter((entry) => entry.file.startsWith(".next/"));
const report = [
  "# Stage 1B public runtime scan",
  "",
  `Generated: ${new Date().toISOString()}`,
  "",
  "## Scope and command",
  "",
  "Scanned .next/server/, .next/static/, and public/ after the production build. Equivalent command: node scripts/scan-stage-1b-public-runtime.mjs. The scan is byte-oriented and includes generated HTML/RSC/metadata/JSON-LD/sitemap/robots output where present.",
  "",
  `Detection terms: ${patterns.join(", ")}.`,
  "",
  "## Results",
  "",
  `- Public public/ marker matches: **${publicMarkerMatches.length}**`,
  `- Build .next/ marker matches: **${nextMarkerMatches.length}**`,
  `- Public old-path matches: **${publicOldPathMatches.length}**`,
  `- Build old-path matches: **${nextOldPathMatches.length}**`,
  `- Public runtime result: **${publicMarkerMatches.length === 0 && publicOldPathMatches.length === 0 ? "PASS" : "FAIL"}**`,
  `- Deployable build result: **${nextMarkerMatches.length === 0 && nextOldPathMatches.length === 0 ? "PASS" : "FAIL"}**`,
  "",
  "## Allowed internal evidence",
  "",
  "Historical audit documents, migration maps, provenance records, and validation scripts intentionally retain old path/status terms as audit evidence. They are outside the scanned deployable runtime scope.",
  "",
  "## Match detail",
  "",
  [...markerMatches, ...oldPathMatches].length ? JSON.stringify({ markerMatches, oldPathMatches }, null, 2) : "No matches found in deployable public files or build output.",
  "",
].join("\n");
fs.writeFileSync(path.join(root, "docs/stage-1b-public-runtime-scan.md"), report);
console.log(JSON.stringify({ publicMarkerMatches: publicMarkerMatches.length, nextMarkerMatches: nextMarkerMatches.length, publicOldPathMatches: publicOldPathMatches.length, nextOldPathMatches: nextOldPathMatches.length }, null, 2));
if (publicMarkerMatches.length || nextMarkerMatches.length || publicOldPathMatches.length || nextOldPathMatches.length) process.exitCode = 1;
